#!/usr/bin/env bash
# Checks that the Constants.scala files generated by Bazel (bazel/constants/*.scala.tpl)
# match the ones Mill generates from project/deps/package.mill, so that both builds
# stay in sync while they coexist. Run after bumping any version in either build:
#   bazel/check-mill-parity.sh
set -euo pipefail
cd "$(dirname "$0")/.."

# mill task | bazel target | bazel output
pairs=(
  "core[].constantsFile|//modules/core:constants|modules/core/Constants.scala"
  "cli[].constantsFile|//modules/cli:constants|modules/cli/Constants.scala"
  "cli[].optionsConstantsFile|//modules/cli:options_constants|modules/cli/options_constants/Constants.scala"
  "tasty-lib[].constantsFile|//modules/tasty-lib:constants|modules/tasty-lib/Constants.scala"
  "docs-tests[].constantsFile|//modules/docs-tests:constants|modules/docs-tests/Constants.scala"
  "build-module[].test.constantsFile|//modules/build:test_constants|modules/build/Constants2.scala"
  "integration.test.constantsFile|//modules/integration:test_constants|modules/integration/Constants.scala"
)

mill_tasks=()
bazel_targets=()
for p in "${pairs[@]}"; do
  IFS='|' read -r task target _ <<< "$p"
  mill_tasks+=("$task" +)
  bazel_targets+=("$target")
done
unset 'mill_tasks[${#mill_tasks[@]}-1]'

./mill -i show "${mill_tasks[@]}" > /dev/null
bazel build "${bazel_targets[@]}"

# Lines expected to differ: the generator comment and machine-specific paths.
normalize() {
  sed -E \
    -e 's|Generated by .*\. \*/|Generated. */|' \
    -e 's|def cs( *)= .*|def cs\1= <cs>|' \
    -e 's|def mostlyStaticDockerfile( *)= .*|def mostlyStaticDockerfile\1= <dockerfile>|' \
    "$1"
}

scala_version="$(sed -nE 's/^SCALA_VERSION = "([^"]*)".*/\1/p' MODULE.bazel)"
status=0
for p in "${pairs[@]}"; do
  IFS='|' read -r task target out <<< "$p"
  # e.g. core[].constantsFile -> out/core/<default Scala version>/constantsFile.dest
  mill_dir="out/$(echo "$task" | sed -E "s/\./\//g; s/\[\]/\/$scala_version/").dest"
  mill_file="$(find "$mill_dir" -name '*.scala' | head -1)"
  if ! diff -u <(normalize "$mill_file") <(normalize "bazel-bin/$out"); then
    echo "MISMATCH: $task ($mill_file) vs $target" >&2
    status=1
  fi
done
[[ $status == 0 ]] && echo "Bazel and Mill generated constants match."
exit $status
